var t=`1134-reuben-sandwich`;var i=`world-1134`;var n=`US`;var r=`northern-america`;var a=4;var o=23;var d={en:`Reuben Sandwich`,ua:`Сендвіч Рубен`};var u={en:`Reuben Sandwich is a dish from United States prepared with rye bread, corned beef, sauerkraut, swiss cheese. This is a home-scale version with measured ingredients in the individual steps where they are used. Mayonnaise replaces the more complex Russian dressing; add a little ketchup or relish to approximate it.`,ua:`Сендвіч Рубен, страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: житній хліб, солонина, квашена капуста, швейцарський сир. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Майонез замінює складніший соус «Рашен»; для наближення додайте кетчуп або реліш.`};var h=[{en:`Toast these ingredients over medium heat for about 6 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 6 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:6,i:[[`rye-bread`,8,`slice`],[`unsalted-butter`,55,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:7,i:[[`corned-beef`,480,`g`],[`sauerkraut`,230,`g`],[`swiss-cheese`,220,`g`],[`mayonnaise`,130,`g`]]},{en:`Pan-fry the prepared food from the previous stages on both sides until browned and fully cooked.`,ua:`Обсмажте підготовлені раніше продукти з обох боків до рум’яної скоринки та повної готовності.`,t:[`pan-frying`],m:10,i:[]}];var l={slug:t,id:i,country:`US`,region:r,servings:4,minutes:23,title:d,text:u,steps:h};export{n as country,l as default,i as id,o as minutes,r as region,a as servings,t as slug,h as steps,u as text,d as title};